<?php require_once __DIR__.'/inc/common.php';require_employee();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT h.*,c.customer_code,c.full_name,c.phone,c.cccd,c.license_number,v.car_code,v.license_plate,v.status AS car_status,m.model_name,e.full_name AS employee_name,r.status AS rental_status FROM contracts h JOIN customers c ON c.id=h.customer_id JOIN cars v ON v.id=h.car_id JOIN car_models m ON m.id=v.model_id JOIN employees e ON e.id=h.employee_id JOIN rentals r ON r.contract_id=h.id WHERE h.id=?');$q->execute([$id?:0]);$h=$q->fetch();if(!$h){http_response_code(404);exit('Không tìm thấy hợp đồng');}page_start('Chi tiết hợp đồng');?><a class="back" href="contracts.php">← Danh sách hợp đồng</a><section class="card printable"><div class="heading"><div><span class="eyebrow">AUK · HỢP ĐỒNG THUÊ XE</span><h1><?=esc($h['contract_code'])?></h1></div><span class="pill">Đã lập thành công</span></div><div class="detail"><span>Khách hàng</span><strong><?=esc($h['full_name'].' ('.$h['customer_code'].')')?></strong><span>Điện thoại</span><strong><?=esc($h['phone'])?></strong><span>CCCD</span><strong><?=esc($h['cccd'])?></strong><span>Giấy phép lái xe</span><strong><?=esc($h['license_number'])?></strong><span>Mẫu xe</span><strong><?=esc($h['model_name'])?></strong><span>Xe / Biển số</span><strong><?=esc($h['car_code'].' · '.$h['license_plate'])?></strong><span>Thời gian thuê</span><strong><?=esc($h['start_date'].' đến '.$h['end_date'])?></strong><span>Số ngày</span><strong><?=intval($h['rental_days'])?></strong><span>Đơn giá/ngày</span><strong><?=money($h['daily_rate'])?></strong><span>Tổng phí thuê</span><strong><?=money($h['total_amount'])?></strong><span>Giao dịch Rental</span><strong><?=esc($h['rental_status'])?></strong><span>Trạng thái xe</span><strong><?=esc($h['car_status'])?></strong><span>Nhân viên lập</span><strong><?=esc($h['employee_name'])?></strong></div><div class="actions"><button class="btn" onclick="window.print()">In hợp đồng</button><a href="index.php" class="btn secondary">Về danh sách</a></div></section><?php page_end();?>
